-- Dash-1 Emperor completion + localized public catalog copy.
-- Production status is a catalog fact and stays distinct from marketplace availability.
-- Rarity is intentionally reset to NULL for Dash-1 releases until the scarcity model
-- is backed by release-specific market evidence.

alter table public.products add column if not exists description_it text;
alter table public.product_releases add column if not exists description text;
alter table public.product_releases add column if not exists description_it text;

update public.products
set description = 'Dash-1 Emperor is Yonkuro Hinomaru''s iconic machine from Dash! Yonkuro. Tamiya introduced the original Type 1 kit as item 18012 in 1988; the design later returned on Type 3, MS and Super-II chassis through standard, special, memorial and premium editions.',
    description_it = 'La Dash-1 Emperor è la celebre macchina di Yonkuro Hinomaru in Dash! Yonkuro. Tamiya introdusse il kit originale con telaio Type 1 e codice 18012 nel 1988; il modello è poi tornato su telai Type 3, MS e Super-II in edizioni standard, speciali, commemorative e Premium.',
    updated_at = now()
where id = '2972e27d-7c75-5534-9ed4-1603ef4a6655';

update public.product_releases set description='The original 1988 Dash-1 Emperor kit, item 18012, using Tamiya''s Type 1 chassis. Its mechanical body shape, roof air intake and rear exhaust details reproduce the manga machine.',description_it='Il kit originale della Dash-1 Emperor del 1988, codice 18012, con telaio Tamiya Type 1. La carrozzeria dal look meccanico, la presa d''aria sul tetto e gli scarichi posteriori riprendono la macchina del manga.',rarity=null,updated_at=now() where id='e1069825-3715-5fa6-80e9-93dcee32d4be';
update public.product_releases set description='The Type 3 commercial version of Dash-1 Emperor, item 18025, first introduced in January 1990. It retains the classic Emperor body while moving the kit to the later Type 3 chassis.',description_it='La versione commerciale della Dash-1 Emperor con telaio Type 3, codice 18025, introdotta inizialmente nel gennaio 1990. Mantiene la classica carrozzeria Emperor adattandola al successivo telaio Type 3.',rarity=null,updated_at=now() where id='96adee91-eaec-5c73-9269-cf3875cfe02d';
update public.product_releases set description='The 2008 Mini 4WD PRO interpretation of Dash-1 Emperor, item 18625. Tamiya adapted the classic body to the three-piece MS chassis while retaining characteristic details of the original design.',description_it='La reinterpretazione Mini 4WD PRO della Dash-1 Emperor del 2008, codice 18625. Tamiya adattò la carrozzeria classica al telaio MS in tre elementi mantenendo i dettagli caratteristici del modello originale.',production_status='active',discontinued=false,status_checked_at=now(),rarity=null,updated_at=now() where id='0306bc1a-cdb6-5b9c-9461-91cd2a39e07c';
update public.product_releases set description='The 2012 Premium version, item 18069, places Dash-1 Emperor on the Super-II chassis with large-diameter wheels and a dedicated sticker set.',description_it='La versione Premium del 2012, codice 18069, porta la Dash-1 Emperor sul telaio Super-II con ruote di grande diametro e un set di adesivi dedicato.',production_status='active',discontinued=false,status_checked_at=now(),rarity=null,barcode_jan=coalesce(barcode_jan,'4950344180691'),updated_at=now() where id='f576fa21-8e57-5fa0-953e-f468653e3767';
update public.product_releases set description='The first 95296 Black Special occurrence, released in 2017 on the MS chassis. It combines a smoke-colored body with fluorescent-yellow MS chassis parts and dedicated metallic-style graphics.',description_it='La prima edizione 95296 Black Special, uscita nel 2017 con telaio MS. Combina carrozzeria color smoke, componenti del telaio MS giallo fluorescente e grafiche dedicate dall''effetto metallizzato.',production_status='discontinued',discontinued=true,status_checked_at=now(),rarity=null,updated_at=now() where id='061cc21a-4382-5bce-b08c-216b456fcaeb';
update public.product_releases set description='The 2018 memorial edition celebrating 30 years of the Japan Cup. Item 95110 uses an MS chassis, a silver-plated Emperor body and special metallic-style commemorative markings.',description_it='L''edizione commemorativa del 2018 dedicata ai 30 anni della Japan Cup. Il codice 95110 utilizza telaio MS, carrozzeria Emperor cromata argento e grafiche commemorative dall''effetto metallizzato.',production_status='active',discontinued=false,status_checked_at=now(),rarity=null,updated_at=now() where id='b7eeb76a-e117-59ae-b31c-b099368421af';
update public.product_releases set description='The documented 2023 reissue of item 95296, again pairing the smoke Dash-1 Emperor body with fluorescent-yellow MS chassis components and dedicated Black Special graphics.',description_it='La ristampa documentata del 2023 del codice 95296, ancora con carrozzeria Dash-1 Emperor color smoke, componenti del telaio MS giallo fluorescente e grafiche dedicate Black Special.',production_status='discontinued',discontinued=true,status_checked_at=now(),rarity=null,updated_at=now() where id='96babc1a-f153-59fa-b840-7ff68fb50f38';
update public.product_releases set description='The 2026 return of item 18025 on the classic Type 3 chassis. Tamiya announced this new production for August 29, 2026 while retaining the traditional Dash-1 Emperor configuration.',description_it='Il ritorno nel 2026 del codice 18025 sul classico telaio Type 3. Tamiya ha annunciato questa nuova produzione per il 29 agosto 2026 mantenendo la configurazione tradizionale della Dash-1 Emperor.',production_status='active',discontinued=false,status_checked_at=now(),rarity=null,updated_at=now() where id='79e32904-fe5d-5d30-bf54-8643ce4b42d3';

insert into public.product_releases
(id,product_id,item_number,release_type,edition_type,edition_name,release_year,release_date,chassis,color,description,description_it,notes,discontinued,is_original,rarity,data_source,verification_status,production_status,status_checked_at)
values
('37ba9a79-6609-5b36-966d-bad0b383eb3a','2972e27d-7c75-5534-9ed4-1603ef4a6655','94666','Special Edition','special','Dash-1 Emperor (Type 3 Chassis) Special Kit',2008,null,'Type 3',null,'The original 2008 Type 3 Special Kit, item 94666. It uses a reinforced polycarbonate-ABS Type 3 chassis and includes both Dash-1 Emperor and Dash-2 Burning Sun bodies with their sticker sets.','Lo Special Kit originale del 2008 con telaio Type 3, codice 94666. Utilizza un telaio Type 3 rinforzato in policarbonato ABS e include sia la carrozzeria Dash-1 Emperor sia la Dash-2 Burning Sun con i relativi adesivi.','Tamiya''s 95622 page identifies August 2008 as the initial release month under item 94666. Tamiya USA explicitly marks 94666 as discontinued.',true,false,null,'tamiya_catalog','verified','discontinued',now()),
('0c785a52-a667-5da5-8a31-9bf0a7f4f7db','2972e27d-7c75-5534-9ed4-1603ef4a6655','94670','Other','other','Dash-1 Emperor (MS Chassis) Finished Model',2008,null,'MS',null,'A factory-finished Dash-1 Emperor on the three-piece MS chassis. Item 94670 was sold already assembled, so it is a distinct commercial format from the unbuilt kits used by TrackDash''s standard sealed-kit market model.','Una Dash-1 Emperor già assemblata in fabbrica sul telaio MS in tre elementi. Il codice 94670 veniva venduto come modello finito e va quindi distinto dai kit da montare utilizzati dal modello di mercato standard di TrackDash.','Factory-finished product. Keep outside new_complete_unbuilt market evidence unless the market condition model explicitly supports finished products.',true,false,null,'tamiya_catalog','verified','discontinued',now()),
('ad3ca562-8d30-517d-8471-9018d26d7af2','2972e27d-7c75-5534-9ed4-1603ef4a6655','94704','Color Special','color_special','Dash-1 Emperor (MS Chassis) Black Special',2009,date '2009-09-12','MS','Smoke Black','The original MS Black Special, item 94704, released in 2009. It features a translucent smoke body, fluorescent-yellow MS chassis components, silver wheels and dedicated Black Special graphics.','La Black Special originale con telaio MS, codice 94704, uscita nel 2009. Presenta carrozzeria semitrasparente color smoke, componenti del telaio MS giallo fluorescente, ruote argento e grafiche dedicate Black Special.','The original Tamiya product page is no longer live. Date and configuration are retained from contemporary reports that referenced the official Tamiya page; production status is intentionally left unknown.',false,false,null,'trusted_secondary','partial','unknown',null),
('9f952d35-333d-5170-860f-1f57542f34e9','2972e27d-7c75-5534-9ed4-1603ef4a6655','94818','Color Special','color_special','Dash-1 Emperor Silver-Plated Body Specification',2011,date '2011-04-28','Type 1','Silver Plated','A limited Dash-1 Emperor specification with a silver-plated body, item 94818, documented for 2011. It keeps the classic Type 1-based Emperor configuration while changing the body finish.','Una versione limitata della Dash-1 Emperor con carrozzeria cromata argento, codice 94818, documentata nel 2011. Mantiene la configurazione classica dell''Emperor basata sul Type 1 modificando la finitura della carrozzeria.','Identity, JAN and 2011-04-28 retailer release date are supported by Japanese specialist retail records; no surviving official Tamiya page was found in this audit, so verification remains partial and production status unknown.',false,false,null,'trusted_secondary','partial','unknown',null),
('2b202422-17d3-5800-9c10-e33541d67e10','2972e27d-7c75-5534-9ed4-1603ef4a6655','95622','Reissue','reissue','Dash-1 Emperor (Type 3 Chassis) Special Kit (2021 Reissue)',2021,date '2021-08-21','Type 3',null,'The 2021 reissue of the Type 3 Special Kit, item 95622. Like the 2008 94666 version, it includes Dash-1 Emperor and Dash-2 Burning Sun bodies and uses a reinforced Type 3 chassis.','La ristampa 2021 dello Special Kit con telaio Type 3, codice 95622. Come la versione 94666 del 2008 include le carrozzerie Dash-1 Emperor e Dash-2 Burning Sun e utilizza un telaio Type 3 rinforzato.','Official Tamiya page states the 2021-08-21 release date and identifies item 94666 from August 2008 as the initial version of this special kit.',false,false,null,'tamiya_catalog','verified','active',now())
on conflict (id) do nothing;

update public.product_releases set barcode_jan='4950344948185',updated_at=now() where id='9f952d35-333d-5170-860f-1f57542f34e9' and barcode_jan is null;

